import{_ as t,o as i,c as a,ag as n}from"./chunks/framework.DNmTgtHf.js";const u=JSON.parse('{"title":"Consolidation Phase Outline (Months 4–9, Weeks 13–38)","description":"","frontmatter":{},"headers":[],"relativePath":"todo/study_plan/reference/ConsolidationOutline.md","filePath":"todo/study_plan/reference/ConsolidationOutline.md"}'),o={name:"todo/study_plan/reference/ConsolidationOutline.md"};function r(s,e,l,d,h,c){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="consolidation-phase-outline-months-4–9-weeks-13–38" tabindex="-1">Consolidation Phase Outline (Months 4–9, Weeks 13–38) <a class="header-anchor" href="#consolidation-phase-outline-months-4–9-weeks-13–38" aria-label="Permalink to &quot;Consolidation Phase Outline (Months 4–9, Weeks 13–38)&quot;">​</a></h1><p>The Sprint covers all 🔴 MUST items + mastery on ~20. Consolidation covers the rest: 🟠 HIGH items at conversant depth, plus deepening of 🔴 items not mastered in Sprint.</p><h2 id="sequencing-principle" tabindex="-1">Sequencing principle <a class="header-anchor" href="#sequencing-principle" aria-label="Permalink to &quot;Sequencing principle&quot;">​</a></h2><ul><li>Cover 🟠 HIGH items across all Parts at conversant depth.</li><li>Deepen remaining 🔴 items not mastered in Sprint (Survey will have flagged these).</li><li>Add 🟡 MED items where they unblock 🟠 understanding.</li></ul><h2 id="provisional-ordering" tabindex="-1">Provisional ordering <a class="header-anchor" href="#provisional-ordering" aria-label="Permalink to &quot;Provisional ordering&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Months</th><th>Focus</th><th>Parts</th></tr></thead><tbody><tr><td>4–5</td><td>Parts deferred from Sprint</td><td>5 (UML), 8 (High TPS), 9 (Caching), 10 (Messaging), 11 (Networking), 12 (API Design)</td></tr><tr><td>6–7</td><td>AWS depth + auth/observability adjacent</td><td>13 (AWS deep), 14 (Cost), 19 (Authorization), 20 (Signing), 21 (Observability)</td></tr><tr><td>8–9</td><td>DevOps + practice rounds</td><td>22 (DevOps), 23 (GenAI), 24 (Engineering practice), 25 (Testing), 26 (Release), 27 (Debugging), 28 (Compliance), 30 (Interview practice — heavy)</td></tr></tbody></table><p>Subject to revision after Sprint completes — actual ordering depends on what mastered well and what still has gaps. Week-by-week scheduling deferred until end of Sprint when actual mastery state is known.</p><h2 id="what-to-do-at-sprint-end" tabindex="-1">What to do at Sprint-end <a class="header-anchor" href="#what-to-do-at-sprint-end" aria-label="Permalink to &quot;What to do at Sprint-end&quot;">​</a></h2><ol><li>List all 🔴 items that did NOT reach Mastery placement.</li><li>List all 🟠 items not yet at Conversant.</li><li>Cluster by Part affinity (related Parts go together).</li><li>Build week-by-week schedule for Months 4-9 against the cluster list.</li><li>Update <code>MasterSchedule.md</code> with Weeks 13-38.</li></ol>',9)])])}const g=t(o,[["render",r]]);export{u as __pageData,g as default};
